namespace sv_4528d987df7348c3a5ab7f977e230609.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(ActiveSection == section.Key ? "active" : "")">
                <button @onclick="() => OnSectionSelected.InvokeAsync(section.Key)">
                    <span class="nav-icon">@section.Icon</span>
                    <span class="nav-label">@section.Label</span>
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private record NavItem(string Key, string Label, string Icon);

    private static readonly NavItem[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings
@using sv_4528d987df7348c3a5ab7f977e230609.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Profile Settings</h2>

    @if (isLoading)
    {
        <div class="loading">Loading profile...</div>
    }
    else if (profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@profile.AvatarUrl" alt="Avatar" class="avatar-image" />
                <p class="avatar-url">@profile.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="profile.Bio" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                    Discard Changes
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</section>

@code {
    private ProfileModel? profile;
    private UserProfile? savedProfile;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        profile = new ProfileModel(savedProfile);
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;

        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new UserProfile(profile.DisplayName, profile.Email, profile.AvatarUrl, profile.Bio);
            await SettingsService.SaveProfileAsync(updated);
            savedProfile = updated;
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            profile = new ProfileModel(savedProfile);
        }
        showSuccess = false;
        errorMessage = null;
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile source)
        {
            DisplayName = source.DisplayName;
            Email = source.Email;
            AvatarUrl = source.AvatarUrl;
            Bio = source.Bio;
        }
    }
}

@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings
@using sv_4528d987df7348c3a5ab7f977e230609.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <div class="loading">Loading notification preferences...</div>
    }
    else if (prefs is not null)
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="prefs.EmailNotifications" />
                    <span class="toggle-label">Email Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="prefs.PushNotifications" />
                    <span class="toggle-label">Push Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="prefs.WeeklyDigest" />
                    <span class="toggle-label">Weekly Digest</span>
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                <ul class="channel-list">
                    @foreach (var channel in availableChannels)
                    {
                        <li class="channel-item">
                            <label>
                                <input type="checkbox"
                                       checked="@prefs.MutedChannels.Contains(channel)"
                                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        </li>
                    }
                </ul>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved successfully!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</section>

@code {
    private NotificationModel? prefs;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    private static readonly string[] availableChannels = ["General", "Announcements", "Engineering", "Marketing", "Support", "Random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var loaded = await SettingsService.GetNotificationPrefsAsync();
        prefs = new NotificationModel(loaded);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (prefs is null) return;

        if (isMuted && !prefs.MutedChannels.Contains(channel))
        {
            prefs.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            prefs.MutedChannels.Remove(channel);
        }
    }

    private async Task SaveAsync()
    {
        if (prefs is null) return;

        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new NotificationPrefs(prefs.EmailNotifications, prefs.PushNotifications, prefs.WeeklyDigest, new List<string>(prefs.MutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(updated);
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private class NotificationModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public NotificationModel(NotificationPrefs source)
        {
            EmailNotifications = source.EmailNotifications;
            PushNotifications = source.PushNotifications;
            WeeklyDigest = source.WeeklyDigest;
            MutedChannels = new List<string>(source.MutedChannels);
        }
    }
}

@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings
@using sv_4528d987df7348c3a5ab7f977e230609.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Security Settings</h2>

    @if (isLoading)
    {
        <div class="loading">Loading security settings...</div>
    }
    else if (security is not null)
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => showPasswordPanel = !showPasswordPanel">
                <span>Change Password</span>
                <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
            </button>

            @if (showPasswordPanel)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                    @if (passwordMessage is not null)
                    {
                        <div class="toast @(passwordSuccess ? "success" : "error")">@passwordMessage</div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <span class="status-indicator @(security.TwoFactorEnabled ? "enabled" : "disabled")">
                    @(security.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            @if (security.LastPasswordChange.HasValue)
            {
                <p class="last-changed">Last password change: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != currentSessionId)
                                {
                                    <button class="btn-danger btn-small" @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn-danger" @onclick="RevokeSessionAsync" disabled="@isRevoking">
                            @(isRevoking ? "Revoking..." : "Yes, Revoke")
                        </button>
