@code {
    private SecuritySettings? security;
    private bool isLoading = true;

    // Password change state
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool isChangingPassword;
    private string? passwordMessage;
    private bool passwordSuccess;

    // Session revoke state
    private ActiveSession? sessionToRevoke;
    private bool isRevoking;
    private string? revokeMessage;
    private bool revokeSuccess;

    private string currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        security = await SettingsService.GetSecuritySettingsAsync();
        if (security.Sessions.Count > 0)
        {
            currentSessionId = security.Sessions[0].Id;
        }
        isLoading = false;
    }

    private async Task ChangePasswordAsync()
    {
        passwordMessage = null;

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordMessage = "New password cannot be empty.";
            passwordSuccess = false;
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordMessage = "New password and confirmation do not match.";
            passwordSuccess = false;
            return;
        }

        isChangingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordMessage = "Password updated successfully!";
            passwordSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordMessage = $"Failed to change password: {ex.Message}";
            passwordSuccess = false;
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        revokeMessage = null;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSessionAsync()
    {
        if (sessionToRevoke is null || security is null) return;

        isRevoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            security = security with
            {
                Sessions = security.Sessions.Where(s => s.Id != sessionToRevoke.Id).ToList()
            };
            revokeMessage = "Session revoked successfully.";
            revokeSuccess = true;
            sessionToRevoke = null;
        }
        catch (Exception ex)
        {
            revokeMessage = $"Failed to revoke session: {ex.Message}";
            revokeSuccess = false;
        }
        finally
        {
            isRevoking = false;
        }
    }
}

