                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                    @if (passwordMessage is not null)
                    {
                        <div class="toast @(passwordSuccess ? "success" : "error")">@passwordMessage</div>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="twofa-status">
                <span class="status-indicator @(security.TwoFactorEnabled ? "enabled" : "disabled")">
                    @(security.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            @if (security.LastPasswordChange.HasValue)
            {
                <p class="last-changed">Last password change: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != currentSessionId)
                                {
                                    <button class="btn-danger btn-small" @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn-danger" @onclick="RevokeSessionAsync" disabled="@isRevoking">
                            @(isRevoking ? "Revoking..." : "Yes, Revoke")
                        </button>
                        <button class="btn-secondary" @onclick="CancelRevoke" disabled="@isRevoking">Cancel</button>
                    </div>
                </div>
            </div>
        }

        @if (revokeMessage is not null)
        {
            <div class="toast @(revokeSuccess ? "success" : "error")">@revokeMessage</div>
        }
    }
</section>

@code {
    private SecuritySettings? security;
    private bool isLoading = true;

    // Password change state
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool isChangingPassword;
    private string? passwordMessage;
    private bool passwordSuccess;

    // Session revoke state
    private ActiveSession? sessionToRevoke;
    private bool isRevoking;
    private string? revokeMessage;
    private bool revokeSuccess;

    private string currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        security = await SettingsService.GetSecuritySettingsAsync();
        if (security.Sessions.Count > 0)
        {
            currentSessionId = security.Sessions[0].Id;
        }
        isLoading = false;
    }

    private async Task ChangePasswordAsync()
    {
        passwordMessage = null;

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordMessage = "New password cannot be empty.";
            passwordSuccess = false;
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordMessage = "New password and confirmation do not match.";
            passwordSuccess = false;
            return;
        }

        isChangingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordMessage = "Password updated successfully!";
            passwordSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordMessage = $"Failed to change password: {ex.Message}";
            passwordSuccess = false;
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        revokeMessage = null;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSessionAsync()
    {
        if (sessionToRevoke is null || security is null) return;

        isRevoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            security = security with
            {
                Sessions = security.Sessions.Where(s => s.Id != sessionToRevoke.Id).ToList()
            };
            revokeMessage = "Session revoked successfully.";
            revokeSuccess = true;
            sessionToRevoke = null;
        }
        catch (Exception ex)
        {
            revokeMessage = $"Failed to revoke session: {ex.Message}";
            revokeSuccess = false;
        }
        finally
        {
            isRevoking = false;
        }
    }
}
"}

