@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings
@using sv_4528d987df7348c3a5ab7f977e230609.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Profile Settings</h2>

    @if (isLoading)
    {
        <div class="loading">Loading profile...</div>
    }
    else if (profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@profile.AvatarUrl" alt="Avatar" class="avatar-image" />
                <p class="avatar-url">@profile.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="profile.Bio" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                    Discard Changes
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</section>

@code {
    private ProfileModel? profile;
    private UserProfile? savedProfile;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        profile = new ProfileModel(savedProfile);
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        if (profile is null) return;

        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new UserProfile(profile.DisplayName, profile.Email, profile.AvatarUrl, profile.Bio);
            await SettingsService.SaveProfileAsync(updated);
            savedProfile = updated;
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            profile = new ProfileModel(savedProfile);
        }
        showSuccess = false;
        errorMessage = null;
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public ProfileModel(UserProfile source)
        {
            DisplayName = source.DisplayName;
            Email = source.Email;
            AvatarUrl = source.AvatarUrl;
            Bio = source.Bio;
        }
    }
}

