@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings
@using sv_4528d987df7348c3a5ab7f977e230609.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <div class="loading">Loading notification preferences...</div>
    }
    else if (prefs is not null)
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="prefs.EmailNotifications" />
                    <span class="toggle-label">Email Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="prefs.PushNotifications" />
                    <span class="toggle-label">Push Notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="prefs.WeeklyDigest" />
                    <span class="toggle-label">Weekly Digest</span>
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                <ul class="channel-list">
                    @foreach (var channel in availableChannels)
                    {
                        <li class="channel-item">
                            <label>
                                <input type="checkbox"
                                       checked="@prefs.MutedChannels.Contains(channel)"
                                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        </li>
                    }
                </ul>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved successfully!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</section>

@code {
    private NotificationModel? prefs;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    private static readonly string[] availableChannels = ["General", "Announcements", "Engineering", "Marketing", "Support", "Random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var loaded = await SettingsService.GetNotificationPrefsAsync();
        prefs = new NotificationModel(loaded);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (prefs is null) return;

        if (isMuted && !prefs.MutedChannels.Contains(channel))
        {
            prefs.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            prefs.MutedChannels.Remove(channel);
        }
    }

    private async Task SaveAsync()
    {
        if (prefs is null) return;

        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new NotificationPrefs(prefs.EmailNotifications, prefs.PushNotifications, prefs.WeeklyDigest, new List<string>(prefs.MutedChannels));
            await SettingsService.SaveNotificationPrefsAsync(updated);
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private class NotificationModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public NotificationModel(NotificationPrefs source)
        {
            EmailNotifications = source.EmailNotifications;
            PushNotifications = source.PushNotifications;
            WeeklyDigest = source.WeeklyDigest;
            MutedChannels = new List<string>(source.MutedChannels);
        }
    }
}

