@namespace sv_4528d987df7348c3a5ab7f977e230609.Components.Pages.Settings
@using sv_4528d987df7348c3a5ab7f977e230609.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Appearance Settings</h2>

    @if (isLoading)
    {
        <div class="loading">Loading appearance settings...</div>
    }
    else if (settings is not null)
    {
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light" @onchange="() => settings.Theme = &quot;Light&quot;" checked="@(settings.Theme == "Light")" />
                        <span>Light</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark" @onchange="() => settings.Theme = &quot;Dark&quot;" checked="@(settings.Theme == "Dark")" />
                        <span>Dark</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System" @onchange="() => settings.Theme = &quot;System&quot;" checked="@(settings.Theme == "System")" />
                        <span>System</span>
                    </label>
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small" @onchange="() => settings.FontSize = &quot;Small&quot;" checked="@(settings.FontSize == "Small")" />
                        <span>Small</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium" @onchange="() => settings.FontSize = &quot;Medium&quot;" checked="@(settings.FontSize == "Medium")" />
                        <span>Medium</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large" @onchange="() => settings.FontSize = &quot;Large&quot;" checked="@(settings.FontSize == "Large")" />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="settings.Language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode Toggle -->
            <div class="form-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="settings.CompactMode" />
                    <span class="toggle-label">Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will appear with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Here's some sample text to demonstrate the appearance.</p>
                    <button class="btn-primary">Sample Button</button>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</section>

@code {
    private AppearanceModel? settings;
    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var loaded = await SettingsService.GetAppearanceAsync();
        settings = new AppearanceModel(loaded);
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        if (settings is null) return "";
        var classes = $"theme-{settings.Theme.ToLowerInvariant()} font-{settings.FontSize.ToLowerInvariant()}";
        if (settings.CompactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        if (settings is null) return;

        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new AppearanceSettings(settings.Theme, settings.FontSize, settings.Language, settings.CompactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private class AppearanceModel
    {
        public string Theme { get; set; }
        public string FontSize { get; set; }
        public string Language { get; set; }
        public bool CompactMode { get; set; }

        public AppearanceModel(AppearanceSettings source)
        {
            Theme = source.Theme;
            FontSize = source.FontSize;
            Language = source.Language;
            CompactMode = source.CompactMode;
        }
    }
}

